python
def positiveTraysThresholdFile(readings, k):
    a=readings
    out=[]
    for x in a:
        if x>0: out.append(x)
    return sum(x>=k for x in out)


java
class Solution {
  public int positiveTraysThresholdFile(int[] readings, int k) {
    int[] a=readings; List<Integer> out=new ArrayList<>();
    {for(int x:a)if(x>0)out.add(x);}
    int answer=0;for(int x:out)if(x>=k)answer++;return answer;
  }
}
